-- DEMO seed (dev/test ONLY, loaded by apps/api/src/db/seed.ts; refused in staging/production).
-- Every row is a fictitious placeholder: content_origin='demo', review_state='draft', no reviewer, no citations.
-- NOT CLINICALLY REVIEWED. No statistics, diagnoses, treatment advice, clinics or contact details.
-- Generated content; edit carefully and keep inserts idempotent (on conflict do nothing).
insert into articles (slug, topic, is_urgent, content_origin) select v.slug, v.topic, v.is_urgent, 'demo' from (values
  ('sti-basics-overview', 'basics', false),
  ('common-stis-overview', 'common-stis', false),
  ('symptoms-and-no-symptoms-overview', 'symptoms', false),
  ('how-stis-spread-overview', 'transmission', false),
  ('prevention-overview', 'prevention', false),
  ('getting-tested-overview', 'testing', false),
  ('treatment-and-follow-up-overview', 'treatment-followup', false),
  ('confidentiality-and-privacy-overview', 'privacy', false),
  ('myths-and-faqs-overview', 'myths-faq', false),
  ('what-to-expect-at-a-clinic', 'clinic-expectations', false),
  ('when-to-seek-a-professional', 'seek-professional', false),
  ('urgent-possible-hiv-exposure-72-hours', 'urgent-exposure', true)
) as v(slug, topic, is_urgent)
on conflict (slug) do nothing;

